(async function() {
    const searchName = '重复条目 (_dup)';
    const targetTag = '_dup'; // 根据你之前的描述，这里设为 _dup，如果是 '_tag' 请自行修改
    const libraryID = Zotero.Libraries.userLibraryID;

    // 1. 创建搜索对象
    let s = new Zotero.Search();
    s.libraryID = libraryID;
    s.setName(searchName);

    // 2. 添加搜索条件：标签 (tag) 是 (is) 指定值
    // 第一个参数是字段名，第二个是运算符，第三个是值
    s.addCondition('tag', 'is', targetTag);

    // 3. 执行保存事务
    // eraseTx 是删除，saveTx 是保存（带数据库事务支持）
    try {
        let searchID = await s.saveTx();

        // 4. 强制刷新界面，让新搜索出现在左侧边栏
        if (typeof ZoteroPane !== 'undefined') {
            await ZoteroPane.collectionsView.refresh();
            // 自动选中新生成的搜索
            ZoteroPane.collectionsView.selectSearch(searchID);
        }

        return `成功创建搜索分类：${searchName} (ID: ${searchID})`;
    } catch (e) {
        return `创建失败：${e.message}`;
    }
})();

(async function() {
    const TAG_NAME = '_dup';
    const libID = Zotero.Libraries.userLibraryID;

    // 1. 查找所有带有该标签的条目
    var s = new Zotero.Search();
    s.libraryID = libID;
    s.addCondition('tag', 'is', TAG_NAME);
    var ids = await s.search();

    if (!ids.length) {
        return "未发现带有 " + TAG_NAME + " 标签的条目。";
    }

    console.log(`正在从 ${ids.length} 个条目中移除标签...`);

    // 2. 使用数据库事务批量处理，提高性能并确保安全
    await Zotero.DB.executeTransaction(async function () {
        for (let id of ids) {
            let item = Zotero.Items.get(id);

            // 3. 移除标签
            item.removeTag(TAG_NAME);

            // 4. 保存更改
            // 使用 skipDateModifiedUpdate: true 可以防止同步时因修改时间变动导致的冲突
            await item.save({
                skipDateModifiedUpdate: true
            });
        }
    });

    // 5. 刷新 UI 界面
    if (typeof ZoteroPane !== 'undefined') {
        ZoteroPane.collectionsView.refresh();
    }

    return `成功移除 ${ids.length} 个条目上的 "${TAG_NAME}" 标签。`;
})();

(async function() {
    const DUP_TAG = '_dup';
    const SAVED_SEARCH_NAME = '重复条目 (_dup)';
    const libID = Zotero.Libraries.userLibraryID;

    console.log('📦 [启动] 正在进行 DOI 深度比对去重...');

    // 1. 获取所有含 DOI 的条目
    let s = new Zotero.Search();
    s.libraryID = libID;
    s.addCondition('DOI', 'isNot', '');
    let ids = await s.search();

    if (ids.length === 0) return "❌ 库中未发现含有 DOI 的条目";
    console.log(`✅ 检索到 ${ids.length} 条含 DOI 的记录，正在拉取详细数据...`);

    // 2. 批量拉取数据并清洗格式
    let doiMap = new Map();
    let items = await Zotero.Items.getAsync(ids);

    for (let item of items) {
        if (!item.isRegularItem()) continue; // 排除附件和笔记

        let rawDoi = item.getField('DOI');
        if (!rawDoi) continue;

        // 强力清洗 DOI 格式：转小写、去 URL 前缀、去后缀斜杠
        let cleanDoi = rawDoi.toLowerCase().trim()
                        .replace(/^https?:\/\/doi\.org\//, "")
                        .replace(/^doi:/, "")
                        .replace(/\/$/, "")
                        .trim();

        if (!doiMap.has(cleanDoi)) doiMap.set(cleanDoi, []);
        doiMap.get(cleanDoi).push(item);
    }

    // 3. 筛选出存在重复的组
    let duplicateGroups = Array.from(doiMap.entries()).filter(([doi, arr]) => arr.length > 1);
    console.log(`📊 发现 ${duplicateGroups.length} 组 DOI 重复。开始按策略标记...`);

    let processedGroups = 0;
    let taggedItemsCount = 0;

    for (let [doi, group] of duplicateGroups) {
        // 策略：1.优先保留有附件的 2.其次保留最早添加的
        group.sort((a, b) => {
            let attA = a.getAttachments().length > 0 ? 1 : 0;
            let attB = b.getAttachments().length > 0 ? 1 : 0;
            if (attA !== attB) return attB - attA; // 有附件的排在前面
            return new Date(a.dateAdded) - new Date(b.dateAdded); // 其次选最早的
        });

        // 第一条作为 "Keep"，其余打标签
        for (let i = 1; i < group.length; i++) {
            let itemToTag = group[i];
            if (!itemToTag.hasTag(DUP_TAG)) {
                itemToTag.addTag(DUP_TAG);
                await itemToTag.saveTx({ skipDateModifiedUpdate: true });
                taggedItemsCount++;
            }
        }

        processedGroups++;

        // 每处理 50 组打印一次进度
        if (processedGroups % 50 === 0) {
            console.log(`⏳ 已检查 ${processedGroups} / ${duplicateGroups.length} 组... (当前已标记 ${taggedItemsCount} 条)`);
        }
    }

    // 4. 创建或更新 Saved Search (Zotero 7 修正版)
    let allSearches = await Zotero.Searches.getAll(libID);
    let existingSearch = allSearches.find(s => s.getName() === SAVED_SEARCH_NAME);

    if (!existingSearch) {
        let ss = new Zotero.Search();
        ss.libraryID = libID;
        ss.setName(SAVED_SEARCH_NAME);
        ss.addCondition('tag', 'is', DUP_TAG);
        await ss.saveTx();
        console.log(`📁 自动分类已创建: ${SAVED_SEARCH_NAME}`);
    }

    console.log(`🏁 [完成] 处理了 ${processedGroups} 组重复，共计标记条目: ${taggedItemsCount}`);

})();

