// --- 1. 配置区 ---
const GEMINI_API_KEY = "AIA";
const MODEL_NAME = "gemini-2.5-flash"; 
const URL = `https://generativelanguage.googleapis.com/v1beta/models/${MODEL_NAME}:generateContent?key=${GEMINI_API_KEY}`;

// --- 2. 获取选中条目与附件 ---
var item = ZoteroPane.getSelectedItems()[0];
if (!item) return "❌ 请先在列表中选中一个条目！";

var attachments = await item.getAttachments();
var pdfItem = attachments.map(id => Zotero.Items.get(id)).find(a => a.isPDFAttachment());
if (!pdfItem) return "❌ 该条目下未找到 PDF 附件。";

try {
    // 3. 读取 PDF 并转换为 Base64 (使用安全读取模式)
    let pdfPath = await pdfItem.getFilePathAsync();
    Zotero.debug(`📂 正在处理文件: ${pdfPath}`);

    let uint8Array = await IOUtils.read(pdfPath);

    // 使用 FileReader 异步转换，避免大文件撑破函数参数栈 (解决 too many arguments)
    let base64Data = await new Promise((resolve, reject) => {
        let blob = new Blob([uint8Array], { type: 'application/pdf' });
        let reader = new FileReader();
        reader.onload = () => resolve(reader.result.split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });

    // --- 4. 构建多模态请求 ---
    Zotero.debug("🚀 正在投喂原生 PDF 数据...");

    let response = await fetch(URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
            contents: [{
                parts: [
                    {
                        inline_data: {
                            mime_type: "application/pdf",
                            data: base64Data
                        }
                    },
                    {
                        text: `你是一个专业的医学专家。请仔细阅读这份 PDF 文档，特别是其中的 Table 和 Results 部分，用中文详细总结：
                        1. 研究的核心结论。
                        2. 提取关键统计数字（发病率、住院率、CFR、OR值等）。
                        3. 【重点提取】：请给出 0-6 月龄儿童 RSV 发病、住院和死亡的具体人数 (Cases) 和率 (Rates)。如果文中区分了胎龄 (GA) 或国家/收入等级，请分别列出。`
                    }
                ]
            }],
            generationConfig: {
                temperature: 0.1, // 降低随机性，确保数字准确
                topP: 0.95
            }
        })
    });

    // --- 5. 处理结果 ---
    let data = await response.json();

    if (data.error) {
        return `❌ API 报错: ${data.error.message}\n状态码: ${data.error.code}`;
    }

    if (!data.candidates || data.candidates.length === 0) {
        return "⚠️ 未能生成有效回复，请检查 API Key 或网络。";
    }

    let aiText = data.candidates[0].content.parts[0].text;

    // 打印到控制台
    Zotero.debug(`✅ 解析完成！字符长度: ${aiText.length}`);

    return `📋 DeepRead 解析结果 [${MODEL_NAME}]:\n\n${aiText}`;

} catch (e) {
    return `❌ 脚本运行出错: ${e.message}\n堆栈: ${e.stack}`;
}
